import {INSTRUMENTS} from './music.js';
import {soundDefinition,normalizeSound,soundPreset,SOUND_PRESETS,WAVEFORMS,envelopePlan,audioTailSeconds} from './sound.js';
import {setTrackSound} from './sound-edit.js';
import {mountSoundBankUI} from './sound-bank-ui.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),round=n=>+n.toFixed(4),format=(value,field)=>field.unit==='比例'?`${Math.round(value*100)}%`:field.unit==='Hz'?`${Math.round(value)} Hz`:`${+value.toFixed(3)} ${field.unit}`;
export function createSoundUI({getProject,getRevision,commit,modal,toast,preview,isQuiet,bank,download}){
 return function showSound(trackId){
  const before=getProject(),at=getRevision(),track=before.tracks.find(t=>t.id===trackId);if(!track)return toast('这条轨道已不存在');const definition=soundDefinition(track.instrument),fields=definition.fields;let draft=normalizeSound(track.instrument,track.sound||{});
  const sliderValue=(field,value)=>field.log?Math.round(Math.log(value/field.min)/Math.log(field.max/field.min)*1000):value;
  const fieldHTML=field=>`<div class="sound-field"><label for="sound-slider-${field.key}"><span>${field.label}</span><output id="sound-output-${field.key}">${format(draft[field.key],field)}</output></label><input id="sound-slider-${field.key}" data-sound-slider="${field.key}" type="range" min="${field.log?0:field.min}" max="${field.log?1000:field.max}" step="${field.log?1:field.step}" value="${sliderValue(field,draft[field.key])}" aria-label="${field.label}"><div class="sound-exact"><small>${field.technical}</small><input id="sound-value-${field.key}" data-sound-value="${field.key}" type="number" min="${field.min}" max="${field.max}" step="${field.step}" value="${draft[field.key]}" aria-label="${field.label}精确值"></div><small>${field.hint}</small></div>`;
  modal('乐器音色 · 不用懂合成器',`<div class="sound-form"><p><strong>${escape(track.name)}</strong> · ${escape(INSTRUMENTS[track.instrument].name)}。影响此轨全部音符，包括共享 Pattern 实例；不改变其他轨道或源乐句。</p><div class="sound-presets">${SOUND_PRESETS.map(p=>`<button class="quiet" data-sound-preset="${p.id}"><strong>${p.name}</strong><small>${definition.kind==='drum'?p.id==='soft'?(track.instrument==='kick'?'鼓体低一点 · 长一点':track.instrument==='snare'?'少一点高频 · 多一点鼓体':'少一点高频 · 长一点'):p.id==='clear'?(track.instrument==='kick'?'鼓体高一点 · 紧一点':'清脆高频 · 紧一点衰减'):'缩短一次击打':p.description}</small></button>`).join('')}</div><label class="check-label"><input id="sound-enabled" type="checkbox" ${track.sound?'checked':''}>启用自定义音色（随工程保存）</label><div class="sound-fields">${fields.filter(f=>!f.advanced).map(fieldHTML).join('')}</div>${definition.kind==='tonal'?`<details class="chord-advanced"><summary>更多设置 / 衰减、滤波突出与波形</summary><div class="sound-fields">${fields.filter(f=>f.advanced).map(fieldHTML).join('')}</div><label class="modal-label" for="sound-waveform">振荡器波形</label><select id="sound-waveform">${Object.entries(WAVEFORMS).map(([id,name])=>`<option value="${id}" ${draft.waveform===id?'selected':''}>${name}</option>`).join('')}</select><p class="review-caption">“原生多层”保留本音源的各层波形。其他选项改变所有振荡器层的波形，层数、音高比与混合比例保留；不是更换插件。</p></details>`:''}<details class="sound-bank-details"><summary>我的音色收藏 · 保存与跨工程复用</summary><div id="sound-bank-panel"></div></details><div id="sound-curve" class="sound-curve" aria-live="polite"></div><label class="sound-demo-length">${definition.kind==='tonal'?'包络示意音符长度':'示意时间窗'}<input id="sound-demo-duration" type="number" min="0.05" max="8" step="0.05" value="1" aria-label="包络示意长度">秒</label><div class="sound-actions"><button class="quiet compact" id="sound-reset">恢复原始音色</button><button class="quiet compact" id="sound-preview">${isQuiet()?'静音检查，不发声':'试听此音色'}</button></div><div class="modal-notice">调整与预设只改草稿；按“应用到此轨”才写入，可以撤销。原始音色保持旧版合成方式，自定义旋律使用线性 ADSR，鼓使用自然衰减。音色写入工程并用于 WAV，MIDI 只带音符 / 乐器程序 / 混音控制，不带这些合成参数。当前${isQuiet()?'安静模式不会创建实时音频上下文':'不会自动试听'}。</div><div id="sound-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="sound-apply">应用到此轨</button>');
  const guard=()=>{if(at!==getRevision())throw Error('工程已改变，请关闭后重新打开音色窗口。')};
  const plan=()=>{guard();const sound=$('#sound-enabled').checked?normalizeSound(track.instrument,draft):undefined;return setTrackSound(getProject(),trackId,sound)};
  const refreshControls=()=>{for(const field of fields){$('#sound-slider-'+field.key).value=sliderValue(field,draft[field.key]);$('#sound-value-'+field.key).value=draft[field.key];$('#sound-output-'+field.key).textContent=format(draft[field.key],field)}if($('#sound-waveform'))$('#sound-waveform').value=draft.waveform};
  const update=()=>{try{const next=plan(),enabled=$('#sound-enabled').checked,length=+$('#sound-demo-duration').value;if(!Number.isFinite(length)||length<.05||length>8)throw Error('示意长度须为 0.05–8 秒');const sound=normalizeSound(track.instrument,draft),points=definition.kind==='tonal'?envelopePlan(length,sound).points:Array.from({length:41},(_,i)=>({time:i*sound.decay/40,value:Math.exp(Math.log(.00001)*i/40)})),end=points.at(-1).time,coords=points.map(p=>`${20+p.time/end*460},${100-p.value*75}`).join(' ');
    $('#sound-curve').innerHTML=`<span class="eyebrow">${enabled?'当前草稿的包络形状':'自定义参数示意 · 尚未启用'} · 不发声</span><svg viewBox="0 0 500 124" role="img" aria-label="${definition.kind==='tonal'?'起音、衰减、持续和释放的包络示意':'鼓声自然衰减示意'}"><path d="M20 25V100H480" stroke="#49545d" fill="none"/><polyline points="${coords}" stroke="#b7d889" stroke-width="2" fill="none"/>${definition.kind==='tonal'?`<path d="M${20+length/end*460} 20V104" stroke="#758c59" stroke-dasharray="3 3"/><text x="${Math.min(425,20+length/end*460)}" y="118">音符结束</text>`:''}</svg><small>${definition.kind==='tonal'?`起音 ${sound.attack} s · 衰减 ${sound.decay} s · 持续 ${Math.round(sound.sustain*100)}% · 释放 ${sound.release} s`:`一次击打 ${sound.decay} s · ${sound.tone} Hz`}<br>${enabled?`应用后 WAV 自动为配置保留 ${audioTailSeconds(next)} 秒尾音。`:'恢复原始音色不会重写音符。下方草稿尚不影响当前工程。'}</small>`;
    $('#sound-error').textContent='';$('#sound-apply').disabled=JSON.stringify(next.tracks.find(t=>t.id===trackId).sound)===JSON.stringify(track.sound);
   }catch(error){$('#sound-error').textContent=error.message;$('#sound-apply').disabled=true;$('#sound-curve').textContent='草稿尚未应用，请检查参数。'}};
  for(const field of fields){$('#sound-slider-'+field.key).oninput=e=>{const value=+e.target.value;draft[field.key]=round(field.log?field.min*Math.pow(field.max/field.min,value/1000):value);$('#sound-value-'+field.key).value=draft[field.key];$('#sound-output-'+field.key).textContent=format(draft[field.key],field);$('#sound-enabled').checked=true;update()};$('#sound-value-'+field.key).oninput=e=>{draft[field.key]=e.target.value===''?NaN:+e.target.value;$('#sound-output-'+field.key).textContent=Number.isFinite(draft[field.key])?format(draft[field.key],field):'待填写';if(Number.isFinite(draft[field.key]))$('#sound-slider-'+field.key).value=sliderValue(field,draft[field.key]);$('#sound-enabled').checked=true;update()}}
  document.querySelectorAll('[data-sound-preset]').forEach(button=>button.onclick=()=>{draft=soundPreset(track.instrument,button.dataset.soundPreset);$('#sound-enabled').checked=true;refreshControls();update()});
  if($('#sound-waveform'))$('#sound-waveform').onchange=e=>{draft.waveform=e.target.value;$('#sound-enabled').checked=true;update()};
  $('#sound-demo-duration').oninput=update;$('#sound-enabled').onchange=update;$('#sound-reset').onclick=()=>{draft=normalizeSound(track.instrument);$('#sound-enabled').checked=false;refreshControls();update()};
  $('#sound-preview').onclick=async()=>{try{guard();const next=plan(),t=next.tracks.find(t=>t.id===trackId);if(isQuiet()){update();return toast('安静模式仅检查包络，没有创建或恢复实时音频上下文。')}await preview(t);toast('只试听草稿音色，没有应用到工程。')}catch(error){$('#sound-error').textContent=error.message}};
  $('#sound-apply').onclick=()=>{try{const next=plan(),custom=!!next.tracks.find(t=>t.id===trackId).sound;if(commit(next)){$('#modal').close();toast(custom?'音色已应用到此轨，音符与共享关系保持。':'此轨已恢复原始音色，可撤销。')}}catch(error){$('#sound-error').textContent=error.message}};update();
  if(bank)mountSoundBankUI({bank,panel:$('#sound-bank-panel'),track,guard,toast,download,getDraft:()=>{guard();return $('#sound-enabled').checked?normalizeSound(track.instrument,draft):null},loadDraft:sound=>{guard();draft=normalizeSound(track.instrument,sound||{});$('#sound-enabled').checked=sound!==undefined;refreshControls();update()}});
 };
}
